import {motionExploration,createMotionInvestigation,removeMotionInvestigation} from './motion-evidence-core.mjs';
import {motionChallenges} from './motion-evidence-adaptive.mjs';
import {motionView,validMotionWork,startMotion,setMotionField,setMotionModel,showMotionHelp,checkMotion,skipMotion,revealMotionData,keepMotion} from './motion-evidence-core.mjs';
import {stopSpeech} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(a,t)=>`<button type="button" class="secondary" ${a}>${esc(t)}</button>`;
function adaptivePanel(state){const v=motionExploration(state);return `<section class="motion-adaptive" aria-labelledby="motion-another"><h2 id="motion-another">Try another investigation</h2><p>Suggested: ${esc(motionChallenges.find(c=>c.id===v.kind)?.title)}. ${esc(v.reason)}</p><p>${esc(v.qualification)}</p>${v.ready?`<label>Choose any concept <select data-motion-challenge>${motionChallenges.map(c=>`<option value="${c.id}" ${v.kind===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label>${btn('data-motion-create','Create another investigation')}`:'<p>New selection is unavailable because optional exploration metadata cannot be read. Saved readable lessons remain open.</p>'}<p>A new visit keeps earlier work. Each concept has six ready-made cases; after that they come back as marked revisits. If a change will not fit, <a href="#notes">download your notes</a> and choose whether to remove a generated visit.</p>${v.ready&&v.visits.length?`<details class="motion-removal"><summary>Choose a generated visit to remove</summary><label>Saved generated visit <select data-motion-remove-select>${v.visits.map(x=>`<option value="${esc(x.id)}">${esc(x.title)} · ${x.checks} checks · ${x.drafts} current writing fields · ${x.kept} kept snapshots · ${esc(x.id)}</option>`).join('')}</select></label>${btn('data-motion-remove','Remove selected generated visit')}<section data-motion-remove-warning hidden><p data-motion-remove-description></p>${btn('data-motion-remove-confirm','Confirm removal of this visit')}${btn('data-motion-remove-cancel','Keep this visit')}</section></details>`:''}</section>`;}
function arrows(w){const {left,right}=w.model,net=right-left;return `<section class="motion-play"><h2>Separate force playground</h2><p>Change these arrows freely. The questions below keep their own numbers. Fixed mass: 2 kg; vertical forces balance; no friction or air resistance in this toy.</p><svg viewBox="0 0 360 145" role="img" aria-label="Left force ${left} N, right force ${right} N on the same cart. Net force ${net} N. Right positive, left negative."><defs><marker id="motion-arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#355e73"/></marker></defs><rect x="150" y="55" width="60" height="48" rx="8" fill="#e7bc74" stroke="#355e73"/><text x="180" y="83" text-anchor="middle">2 kg</text>${left?`<path d="M150 69H${150-left*15}" marker-end="url(#motion-arrow)" stroke="#355e73" stroke-width="4"/>`:''}${right?`<path d="M210 90H${210+right*15}" marker-end="url(#motion-arrow)" stroke="#355e73" stroke-width="4"/>`:''}<text x="55" y="40">← ${left} N</text><text x="250" y="40">${right} N →</text><text x="180" y="133" text-anchor="middle">left − · right +</text></svg>${['left','right'].map(k=>`<label>${k==='left'?'Leftward':'Rightward'} force · N<input type="range" min="0" max="8" step="2" value="${w.model[k]}" data-motion-model="${k}"><output>${w.model[k]} N</output></label>`).join('')}<p class="motion-result" aria-live="polite">Net force: ${right} − ${left} = ${net>0?'+':''}${net} N. Acceleration: ${net/2>0?'+':''}${net/2} m/s².</p><p>For this fixed 2 kg mass, acceleration = net force ÷ 2 kg. This is velocity change per second, not velocity.</p></section>`;}
function constantMotion(){return `<figure class="motion-positions"><svg viewBox="0 0 360 125" role="img" aria-label="Zero net force: a moving cart has positions 280, 220, 160, 100 at equal one-second times, continuing left at constant speed. A resting cart stays at one position."><text x="8" y="20">Moving left · equal time steps</text>${[280,220,160,100].map((x,n)=>`<circle cx="${x}" cy="45" r="9" fill="#355e73"/><text x="${x}" y="70" text-anchor="middle">${n} s</text>`).join('')}<text x="8" y="110">At rest · all times at the same position ●</text></svg><figcaption>Balanced forces keep the velocity unchanged in this model.</figcaption></figure>`;}
function table(s){return `<p>Scroll the table sideways to read every column on a narrow screen.</p><div class="motion-table" tabindex="0" aria-label="Collision data table, scroll sideways for more columns"><table><caption>Invented collision trials · ${esc(s.collisionModel?`same ${s.collisionModel.mass} kg cart, ${s.collisionModel.startVelocity>0?'+':''}${s.collisionModel.startVelocity} m/s → ${s.collisionModel.endVelocity} m/s`:'same 2 kg cart, +2 m/s → 0 m/s')}</caption><thead><tr><th>Design</th><th>${s.adaptive?'Lasting shape change':'Shape change'} (cm)</th><th>Stopping time (s)</th><th>Average net force magnitude (N) · model inference</th><th>Cost (tokens)</th><th>Depth (cm)</th></tr></thead><tbody>${s.data.map(d=>`<tr><th scope="row">${esc(d.name)}</th><td>${d.shape}</td><td>${d.time.toFixed(2)}</td><td>${s.adaptive?Number(d.average.toPrecision(3)):d.average}</td><td>${d.cost}</td><td>${d.depth}</td></tr>`).join('')}</tbody></table></div><p>Average net stopping force opposes the initial motion; the table reports its positive magnitude. Shape change and stopping time are invented measurements given in the table. The average force column is calculated, not directly measured. None of these cases measures peak force, injury or durability.</p>`;}
function task(w,q){const c=w.checks.filter(c=>c.itemId===q.id).at(-1),blocked=w.source.newMessage&&q===w.source.items[1]&&!w.newData;return `<section class="motion-task" id="motion-item-${esc(q.id)}" tabindex="-1" data-motion-item="${esc(q.id)}"><h3>${esc(q.prompt)}</h3>${blocked?'<p>Reveal the new requirement first; every other lesson remains open.</p>':`<fieldset><legend>Your choice</legend>${q.choices.map(a=>`<label><input type="radio" name="motion-${esc(q.id)}" data-motion-field="${esc(q.id)}" value="${esc(a.id)}" ${w.drafts[q.id]===a.id?'checked':''}>${esc(a.text)}</label>`).join('')}</fieldset>${btn(`data-motion-check="${esc(q.id)}"`,'Check this choice')}`}${c?`<p class="motion-feedback" role="status">${c.outcome==='match'?'Fits this case.':'Try another comparison.'} ${esc(c.feedback)} Last response: ${esc(q.choices.find(a=>a.id===c.raw)?.text)}</p>`:''}<div class="motion-actions">${['guided','hint','example'].map(k=>btn(`data-motion-help="${esc(q.id)}:${k}"`,{guided:'Guided case',hint:'Hint',example:'Different example'}[k])).join('')}${btn(`data-motion-skip="${esc(q.id)}"`,w.skips.includes(q.id)?'Skipped for now · you can return':'Skip for now')}</div>${['guided','hint','example'].filter(k=>w.help.includes(`${q.id}:${k}`)).map(k=>`<aside class="motion-help"><strong>${{guided:'Guided case',hint:'Hint',example:'Different example'}[k]}</strong><p>${esc(q[k])}</p></aside>`).join('')}</section>`;}
function writing(w){return `<section class="motion-writing"><h2>Your explanation · human-read, ungraded</h2><label>${esc(w.source.writing)}<textarea maxlength="1200" rows="4" data-motion-field="explanation">
${esc(w.drafts.explanation)}</textarea></label>${btn('data-motion-keep','Keep this version')}${w.firstKept?`<details><summary>First kept explanation</summary><p>${esc(w.firstKept.drafts.explanation)||'(blank)'}</p></details>`:''}${w.kept?'<p>Latest kept version saved. Your original words have no automatic score.</p>':''}</section>`;}
export function motionPage(state,requestedId){const v=motionView(state),requested=v.lessons.find(l=>l.id===requestedId),w=requestedId&&requestedId!==state.motionEvidence?.currentId?null:v.work;return `<div class="motion-page" data-motion-root><header><a class="back" href="#pathways">Choose a subject</a><p>Science · five connected lessons</p><h1 id="motion-heading" tabindex="-1">Motion and evidence</h1><p>Follow force arrows, explain a change of motion, then choose within a limited set of collision data. All lessons stay open.</p></header>${v.status==='unavailable'?'<p>This saved format is retained unchanged. Other places remain open.</p><a href="#notes">Open your notes</a>':`${adaptivePanel(state)}<nav class="motion-lessons" aria-label="Motion lessons">${v.lessons.map(l=>l.unreadable?`<p>${esc(l.title)}: earlier work retained; this lesson cannot be edited here.</p>`:btn(`data-motion-start="${esc(l.id)}" aria-pressed="${w?.source.id===l.id}"`,l.title)).join('')}</nav>${requested&&!w&&!requested.unreadable?`<section><h2>${esc(requested.title)}</h2><p>Open this lesson explicitly. Your waiting lesson and its drafts are retained.</p>${btn(`data-motion-start="${esc(requested.id)}"`,'Start or continue this lesson')}</section>`:''}${w?`<article><h2>${esc(w.source.title)}</h2>${w.source.adaptive?`<p>${w.source.adaptive.revisit?'Revisiting a ready-made case.':'A new visit to this ready-made case.'} Every choice remains open; original writing is human-read.</p>`:''}<p>${esc(w.source.intro)}</p><aside class="motion-teach"><h3>Learn</h3><p>${esc(w.source.teach)}</p></aside>${(['arrows','acceleration'].includes(w.source.id)||w.source.adaptive?.kind==='forces')?arrows(w):w.source.id==='balanced'?constantMotion():''}${w.source.data?table(w.source):''}${w.source.items.map((q,i)=>`${i===1&&w.source.newMessage?`${w.source.writing?writing(w):''}<section class="motion-new">${btn('data-motion-new','Reveal the new requirement')}${w.newData?`<p>${esc(w.source.newMessage)}</p>`:''}</section>`:''}${task(w,q)}`).join('')}${w.source.writing&&w.newData?`<section class="motion-writing"><label>Revise after the new requirement. What changed, and what is still unknown?<textarea maxlength="1200" rows="4" data-motion-field="revision">
${esc(w.drafts.revision)}</textarea></label>${btn('data-motion-keep','Keep revision')}</section>`:''}</article>`:!requested?'<p>Choose any lesson to start or continue. Nothing here is timed or locked.</p>':''}`}<p id="motion-status" role="status" aria-live="polite" tabindex="-1"></p><footer><a href="#science">Other science places</a><a href="#notes">Grown-up notes</a></footer></div>`;}
export function motionNotes(state){if(!Object.hasOwn(state,'motionEvidence'))return '';const v=motionView(state);return `<details class="panel"><summary>Motion and evidence · supplied-model practice</summary><p>All responses use supplied source material. Recent choices, help and skips are separate. Free explanations and revisions are human-read and ungraded. Invented trials do not approve real protective designs or show practical competence.</p>${v.status==='unavailable'?'<p>Earlier format retained unchanged.</p>':Object.entries(state.motionEvidence.lessons).map(([k,w])=>`<p>${esc(validMotionWork(w)?w.source.title:k)}: ${validMotionWork(w)?`${w.checks.length} recent checks; ${w.skips.length} skips; first kept ${w.firstKept?'yes':'no'}, latest kept ${w.kept?'yes':'no'}.`:'earlier unreadable lesson retained.'}</p>`).join('')}<details><summary>Exact sources, raw drafts, support and outcomes</summary><pre>${esc(JSON.stringify(state.motionEvidence,null,2))}</pre></details></details>`;}
export function bindMotion(state,{save,render,focus,canExport,explorerId,isActive,entryLesson}={}){const root=document.querySelector('[data-motion-root]');if(!root)return;const owner=explorerId?.(),route=location.hash,o={canExport};const dirtyFields=new Set();const live=el=>root.isConnected&&el.isConnected&&root.contains(el)&&location.hash===route&&(!isActive||isActive())&&explorerId?.()===owner;const say=t=>{const e=root.querySelector('#motion-status');if(e)e.textContent=t;};const fail=()=>say('This change could not be saved safely. Your earlier work is unchanged. Keep any unsaved words here or copy them before leaving. You can download notes and explicitly remove a selected generated visit if space is needed.');const redraw=(msg='',target='#motion-heading')=>{stopSpeech();save?.();render?.();focus?.(target);const e=document.querySelector('#motion-status');if(e)e.textContent=msg;};const click=(selector,fn)=>root.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(!live(b))return;if(dirtyFields.size)return fail();fn(b);}));
 click('[data-motion-create]',()=>{const kind=root.querySelector('[data-motion-challenge]')?.value;const key=createMotionInvestigation(state,kind,o);if(!key)return fail();location.hash='#learn/science/'+key;redraw('New source saved; earlier visits retained.');});
 click('[data-motion-remove]',()=>{const key=root.querySelector('[data-motion-remove-select]')?.value,v=motionExploration(state).visits.find(x=>x.id===key),box=root.querySelector('[data-motion-remove-warning]');if(!v||!box)return fail();box.hidden=false;box.querySelector('[data-motion-remove-description]').textContent=`Remove ${v.title} (${v.id})? This removes its frozen source, choices, ${v.checks} checks, ${v.drafts} current original/revision writing fields and ${v.kept} first/latest kept snapshots including their writing. Other visits and fixed lessons stay saved. Download notes first if you want a copy.`;box.querySelector('[data-motion-remove-confirm]').dataset.key=key;box.querySelector('[data-motion-remove-confirm]').focus();});
 click('[data-motion-remove-cancel]',()=>{const box=root.querySelector('[data-motion-remove-warning]');box.hidden=true;root.querySelector('[data-motion-remove]').focus();});
 click('[data-motion-remove-confirm]',b=>{if(!removeMotionInvestigation(state,b.dataset.key,true,o))return fail();location.hash='#learn/science';redraw('Selected generated visit removed.');});
 click('[data-motion-start]',b=>{if(!startMotion(state,b.dataset.motionStart,o))return fail();if((entryLesson||route.split('/')[2])&&b.dataset.motionStart!==(entryLesson||route.split('/')[2]))location.hash='#learn/science/'+b.dataset.motionStart;redraw();});
 root.querySelectorAll('[data-motion-field]').forEach(e=>e.addEventListener(e.type==='radio'?'change':'input',()=>{if(!live(e))return;const ok=setMotionField(state,e.dataset.motionField,e.value,o);if(ok)dirtyFields.delete(e.dataset.motionField);else dirtyFields.add(e.dataset.motionField);if(!ok)return fail();save?.();say('Draft saved.');}));
 root.querySelectorAll('[data-motion-model]').forEach(e=>e.addEventListener('input',()=>{if(!live(e)||dirtyFields.size)return;const ok=setMotionModel(state,e.dataset.motionModel,Number(e.value),o);if(!ok)return fail();save?.();const temp=document.createElement('template');temp.innerHTML=motionPage(state);const updated=temp.content.querySelector('.motion-play');root.querySelector('.motion-play svg').replaceWith(updated.querySelector('svg'));root.querySelector('.motion-result').replaceWith(updated.querySelector('.motion-result'));e.nextElementSibling.textContent=`${e.value} N`;say('Playground changed; the question keeps its own numbers.');}));
 click('[data-motion-help]',b=>showMotionHelp(state,b.dataset.motionHelp,o)?redraw('Help opened.',`#motion-item-${b.dataset.motionHelp.split(':')[0]}`):fail());
 click('[data-motion-check]',b=>{if(!motionView(state).work?.drafts[b.dataset.motionCheck])return say('Choose a response first, or skip for now.');const r=checkMotion(state,b.dataset.motionCheck,o);r?redraw(r.feedback,`#motion-item-${b.dataset.motionCheck}`):fail();});
 click('[data-motion-skip]',b=>skipMotion(state,b.dataset.motionSkip,o)?redraw('Skipped for now. You can return.',`#motion-item-${b.dataset.motionSkip}`):fail());
 click('[data-motion-new]',()=>revealMotionData(state,o)?redraw('New requirement shown; first explanation retained.','#motion-status'):fail());
 click('[data-motion-keep]',()=>keepMotion(state,o)?redraw('Version kept without a prose grade.','#motion-status'):fail());
}
